async def get_hello(data: FilterableStr | None = Query(default=None)) -> Any:
    return data

if __name__ == "__main__":
    try:
        from fastapi.testclient import TestClient
        client = TestClient(app)
        client.get("/hello")
    except AssertionError as e:
        print(f"Caught expected AssertionError: {e}")
        if "Query param 'data' must be of one of the supported types" in str(e):
            print("SUCCESS: Error message is correct")
        else:
            print(f"FAILURE: Error message was {e}")
            exit(1)
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        exit(1)
